con.execute("insert into Unit (UnitID, ContainerID, Contents) values (?, ?, ?)", (m, None, bson.encode(mod)))
con.execute("insert into Unit (UnitID, ContainerID, Contents) values (?, ?, ?)", (p, m, bson.encode(page))); con.commit()
