    'REMOVE +vendorlib/commons-logging-1\.2\.jar' 'KEEP +userlib/guava-32\.0\.jar +CONFLICT .*PresentMod' '!REMOVE +userlib/guava-32' 'KEEP +vendorlib/guava-33\.0\.jar +newest' \
