NR=$T/norsync; mkdir -p $NR   # PATH without rsync: every other command on PATH, linked
for d in $(echo "$PATH" | tr ':' ' '); do for f in "$d"/*; do n=${f##*/}; [ "$n" = rsync ] || [ -e "$NR/$n" ] || ln -s "$f" "$NR/$n" 2>/dev/null; done; done
