echo '{"widgetId": "com.x.Grid"}' > $GW/app/.mxcli/widgets/Grid.def.json
(cd $GW/app && git init -q && echo base > readme.txt && git add readme.txt && git -c user.email=c@c -c user.name=ctl commit -qm base)
