{ sed -n '/^kept_vendor_check() {/,/^}/p' ${PIPE:-$B/cloud/upgrade-pipeline.sh}
  printf '%s\n' 'x() { "$@"; }' 'xo() { local o=$1; shift; "$@" > "$o" 2>&1; }' 'note() { echo "NOTE: $*"; }' 'nj_meta() { :; }' 'nj_file() { echo "NJ: $2 | $3 | $5"; }' \
