    -- python3 $B/apimock.py inventory $SU
  SP=$AM/stp
  ctl apimock-uncalled-serve-pass 0 '^Mod\.OldServiceUrl=http://127\.0\.0\.1:[0-9]+/c/Mod\.OldServiceUrl/$' \
