ctl apidirect-volatile-ids-pass 0 'PASS 1' '!FAIL' -- python3 $B/apidirect.py compare --state $AD/volatile
# apimock check: a --classify EXCLUDED line is INFO (exit 0), and --direct measured endpoints need no journey hit
python3 - "$AD" <<'EOF'
