GSJ="$DR; a.names=lambda q: set(); a.landing=lambda q, away=None: None; a.tab_acts = lambda h, page: ([], [])
x = {'id': 'M.S3.actionButton1', 'action': 'microflow', 'kind': 'commit', 'host': 'S3', 'widget': 'actionButton1', 'caption': 'Retry', 'path_role': 'R',
