RJS="import sys; sys.path.insert(0, '$B'); import run_journeys as rj
j = {'steps': [{}, {'shown_if': ['go: c']}, {}]}; P, F = {'checks': [{'verdict': 'PASS'}]}, {'checks': [{'verdict': 'FAIL'}]}"
ctl journeys-shown-if-at-pass 0 "^fail \['go: c'\] stopped \['go: c'\] first None all None$" \
