# ssum.sh WORK: one line per step: id, topic, alias, approval state, by, source, whether found and proposed are set
cat > $PR/ssum.sh <<'SH'
#!/bin/bash
python3 "$B/steps.py" show --work "$1" --json | python3 -c '
