# harvest.py: a made-up run folder with one fix of each kind (a repair row, a fix BACKLOG #102 names, a fix nobody
# names), an error code no toolkit file names, a script the agent wrote and a gate WARNING; a made-up brain that holds
# mx.logger and the code (so the code gets no brain draft, the new fix does). The denylist (Acmecorp, set above) refuses
# a draft; a bad code name is refused before anything is read.
HV=$T/harvest; mkdir -p $HV/run $HV/brain/internal/upgrade $HV/run-deny
hv_changes() {  # $1 file, $2 extra why text of the new fix
  printf '%s\n' '| # | when | by | kind | rule | why | what changed | evidence | step |' '|---|---|---|---|---|---|---|---|---|' \
    '| 1 | 2026-11-10 | agent | repair | repair-row-13 | 3 pages repointed from Logging.PopupLayout (`a64fbf1`) | model changed | x.log | no step |' \
    '| 2 | 2026-11-10 | agent | repair | decision-mxlogger | Mendix 11 removed mx.logger: MicroflowTimer logs via console | 2 files | x.log | no step |' \
    "| 3 | 2026-11-10 | agent | repair | decision-frob | Widget_Fake.FrobAction() replaced by a nanoflow$2 | 1 file | x.log | no step |" \
    '| 4 | 2026-11-10 | toolkit | config | build-stubs | regenerated stubs | 9 files | none | housekeeping |' > $1
}
hv_changes $HV/run/CHANGES.md ''
printf 'mx check: CE9987 frob widget has no successor\n' > $HV/run/check.log
printf '#!/usr/bin/env python3\n# Rewrite the frob widgets on every page of the app\nprint(1)\n' > $HV/run/frob_fix.py
# files the pipeline writes itself are no agent script (cold CMM: 37 listed): a patched engine copy, replay MDL, saved edits
mkdir -p $HV/run/e2e-base/engine $HV/run/replay $HV/run/saved-edits/Mod; printf '// patched engine copy\n' > $HV/run/e2e-base/engine/helpers.js
printf '/* replay of Mod */\n' > $HV/run/replay/Mod.mdl; printf -- '-- CONSTANT Key, as it stands\n' > $HV/run/saved-edits/Mod/constant-Key.mdl
printf '| 1 | WARNING: trail: 2 gap(s) in 2 steps |\n' > $HV/run/gate-summary.md
# NL1 (field run): <work>/run/<app>/web/... is the unpacked deployment; the path names are from a real run folder, the content is a stub
mkdir -p $HV/run/run/oldwalk/web/js $HV/run/run/oldwalk/tmp; printf 'define(["react"],(function(e){return e}));\n' > $HV/run/run/oldwalk/web/js/login.js
printf 'export const A = async () => 1;\n' > $HV/run/run/oldwalk/tmp/jsactions.js
printf -- '---\ntitle: mx.logger is gone in 11\nconfidentiality: internal\n---\nmx.logger calls crash on 11, CE9987 too.\n' > $HV/brain/internal/upgrade/mx-logger.md
hv_changes $HV/run-deny/CHANGES.md ' for the Acmecorp portal'
hv() { python3 -I $B/harvest.py --code HV1 --brain $HV/brain --date 2026-01-02 "$@"; }
ctl harvest-run-pass 0 '^harvest: 3 agent fixes \(2 known to the toolkit, 1 new\), 1 new error codes, 1 scripts, 1 toolkit items$' \
  -- hv --work $HV/run --inbox $HV/tk --brain-inbox $HV/bi
ctl harvest-new-fix-catch 0 'decision-frob.*Widget_Fake\.FrobAction\(\)' '!decision-mxlogger.*\[CHANGES' -- sed -n '/^## Fixes the agent made/,/^## Known/p' $HV/tk/2026-01-02-HV1-harvest.md
ctl harvest-known-fix-pass 0 'repair-row-13.*\[known: steps/repair\.md row 13\]' 'decision-mxlogger.*\[known: BACKLOG\.md #102' -- cat $HV/tk/2026-01-02-HV1-harvest.md
ctl harvest-code-script-item-pass 0 '^- CE9987 ' 'frob_fix\.py \(3 lines\): Rewrite the frob widgets' 'trail: 2 gap' '!CE1613' -- cat $HV/tk/2026-01-02-HV1-harvest.md
ctl harvest-deployed-run-folder-not-a-script-catch 0 'frob_fix\.py' '!login\.js' '!jsactions\.js' -- cat $HV/tk/2026-01-02-HV1-harvest.md
ctl harvest-toolkit-written-pass 0 'frob_fix\.py' '!e2e-base/engine' '!replay/Mod' '!saved-edits/' -- cat $HV/tk/2026-01-02-HV1-harvest.md
ctl harvest-brain-lookup-pass 0 '^- CE9987 .*brain has a note' 'decision-frob.*brain has no note' -- cat $HV/tk/2026-01-02-HV1-harvest.md
ctl harvest-brain-draft-pass 0 'confidentiality: internal' 'status: draft-unreviewed' 'Widget_Fake\.FrobAction\(\)' '!mx\.logger calls crash' '!CE9987' -- cat $HV/bi/2026-01-02-HV1-upgrade.md
ctl harvest-scrub-pass 0 '!'"$HV" -- cat $HV/tk/2026-01-02-HV1-harvest.md $HV/bi/2026-01-02-HV1-upgrade.md
ctl harvest-denylist-catch 1 'Acmecorp' '!^harvest: wrote' -- sh -c "python3 -I $B/harvest.py --code HV1 --brain $HV/brain --date 2026-01-02 --work $HV/run-deny --inbox $HV/tk-deny --brain-inbox $HV/bi-deny 2>&1; rc=\$?; ls $HV/tk-deny 2>/dev/null; exit \$rc"
ctl harvest-denylist-wrote-nothing-pass 0 '^none$' -- sh -c "ls $HV/tk-deny/*.md 2>/dev/null || echo none"
ctl harvest-bad-code-catch 2 'code' -- python3 -I $B/harvest.py --work $HV/run --code 'a b' --inbox $HV/tk-bad
ctl harvest-denied-code-catch 2 'code' -- python3 -I $B/harvest.py --work $HV/run --code Acmecorp --inbox $HV/tk-bad
# a brain inside the toolkit checkout is read, never written: its drafts go to <work>/learnings/brain
cp -R $HV/run $HV/run-sh; cp -R $HV/run $HV/run-home; mkdir -p $HV/home/Mendix/x-brain/baseline/versions $HV/home/Mendix/x-brain/internal/upgrade
: > $HV/home/Mendix/x-brain/baseline/versions/studio-pro-upgrade-11.md; cp $HV/brain/internal/upgrade/mx-logger.md $HV/home/Mendix/x-brain/internal/upgrade/
# a stand-in toolkit checkout under $T (a copy of the bin and the brain fixture): a red run must not leave an inbox/ in the real checkout
mkdir -p $HV/ftk/upgrade-toolkit; cp -R $B $HV/ftk/upgrade-toolkit/bin; cp -R $FX/brain-notes $HV/ftk/brain-copy
ctl harvest-toolkit-brain-draft-to-work-catch 0 '^  brain: .* is the brain shipped in the toolkit \(read only\)' "learnings/brain/2026-01-03-HV1-upgrade\\.md" '^NOT-IN-BRAIN$' -- sh -c "env -u UPG_BRAIN python3 -I $HV/ftk/upgrade-toolkit/bin/harvest.py --code HV1 --brain $HV/ftk/brain-copy --date 2026-01-03 --work $HV/run-sh --inbox $HV/tk-sh --to brain; [ -d $HV/ftk/brain-copy/inbox ] && echo WROTE-INTO-BRAIN || echo NOT-IN-BRAIN"
# a brain without internal/: the first `harvest:` line stays the summary (feedback_report.py shows the first one), the skip note follows, no path
mkdir -p $HV/brain-noint/baseline; cp -R $HV/run $HV/run-noint
ctl harvest-no-internal-summary-first-catch 0 '^harvest: 3 agent fixes' '^  brain: the brain has no internal/ folder' '!^harvest: .*no internal' '!brain-noint' -- sh -c "python3 -I $B/harvest.py --code HV1 --brain $HV/brain-noint --date 2026-01-05 --work $HV/run-noint --inbox $HV/tk-noint --to brain 2>&1"
ctl harvest-brainpath-default-pass 0 "x-brain/inbox/2026-01-04-HV1-upgrade\\.md" '!not configured' -- sh -c "env -u UPG_BRAIN -u UPG_BRAIN_SHIPPED HOME=$HV/home python3 -I $B/harvest.py --code HV1 --date 2026-01-04 --work $HV/run-home --inbox $HV/tk-home --to brain"
# feedback_report.py (cold WM1): harvest ran only when a person remembered steps/report.md 3c, so a stopped run taught the
# toolkit nothing. Every exit now harvests into $WORK/learnings and writes FEEDBACK-REPORT.md with an issue summary
# (metadata only, denylisted); the pipeline calls it from its exit trap, so a stop (exit 4 at build) gets one too.
FB=$T/feedback; mkdir -p $FB; cp -R $HV/run $FB/run; cp -R $HV/run $FB/nocode; cp -R $HV/run $FB/deny; cp -R $HV/run $FB/trap
printf '## Acmecorp portal module kept\n' > $FB/deny/NEEDS-JUDGMENT.md
fbr() { env -u UPG_BRAIN -u UPG_HARVEST python3 -I $B/feedback_report.py "$@"; }
ctl feedback-report-pass 0 '^feedback: .*FEEDBACK-REPORT\.md \(1 draft' -- fbr --work $FB/run --exit 4 --step build --code HV1 --source 9.24.0 --target 10.24.0
ctl feedback-report-content-pass 0 '^Exit 4 at build: a fixed step failed' '^harvest: 3 agent fixes' '^- `learnings/[0-9-]+-HV1-harvest\.md`' 'stopped at step: build' 'upgrade 9\.24\.0 -> 10\.24\.0' 'submit-learnings\.sh toolkit' -- cat $FB/run/FEEDBACK-REPORT.md
ctl feedback-report-nocode-pass 0 '^feedback: .*\(0 draft' -- fbr --work $FB/nocode --exit 13
ctl feedback-report-nocode-says-pass 0 'skipped: no app code name' '^Exit 13 at the end of the run' -- cat $FB/nocode/FEEDBACK-REPORT.md
fbr --work $FB/deny --exit 13 --code HV1 > /dev/null 2>&1 || true
ctl feedback-report-deny-catch 0 'left out: it matches the private denylist' '!Acmecorp' -- cat $FB/deny/FEEDBACK-REPORT.md
{ awk '/^app_code\(\) \{/,/^}$/;/^feedback_finish\(\) \{/,/^}$/' $B/cloud/upgrade-pipeline.sh; awk '/^cleanup\(\) \{/,/^}$/' $B/cloud/upgrade-pipeline.sh
  printf '%s\n' 'timing_close() { :; }' "B=$B; WORK=$FB/trap; DRY=0; STEP=build; UPG_APP_CODE=HV1; APPS_UP=()" 'trap cleanup EXIT' 'exit 4'; } > $FB/trap.sh
ctl pipeline-feedback-on-exit-pass 0 '^rc=4$' '^Exit 4 at build' -- sh -c "env -u UPG_BRAIN bash $FB/trap.sh > /dev/null 2>&1; echo rc=\$?; cat $FB/trap/FEEDBACK-REPORT.md"
# backlog 153 (cold CMM): no app code anywhere, harvest and the run log skipped. app_code derives a neutral app-<6 hex>
# from the .mpr file name (no name in it), writes it to the rung 1 state/app-code, and rung 2 reads the same one
AC=$T/appcode; mkdir -p $AC/app $AC/run/work/rung2 $AC/kept/work/state; : > "$AC/app/Acmecorp Orders.mpr"; echo KEEP1 > $AC/kept/work/state/app-code
awk '/^app_code\(\) \{/,/^}$/' ${PIPE:-$B/cloud/upgrade-pipeline.sh} > $AC/fn.sh
ctl pipeline-app-code-derived-catch 0 '^code=app-[0-9a-f]{6}$' '^state=app-[0-9a-f]{6}$' '^rung2=app-[0-9a-f]{6}$' '!rung2-own' '!Acmecorp' -- bash -c "env -u UPG_APP_CODE -u UPG_APP_NAME bash -c '. $AC/fn.sh; APP=$AC/app WORK=$AC/run/work DRY=0; echo code=\$(app_code); echo state=\$(cat $AC/run/work/state/app-code); WORK=$AC/run/work/rung2; echo rung2=\$(app_code); [ ! -e $AC/run/work/rung2/state/app-code ] || echo rung2-own'"
ctl pipeline-app-code-kept-pass 0 '^code=KEEP1$' -- bash -c "env -u UPG_APP_CODE -u UPG_APP_NAME bash -c '. $AC/fn.sh; APP=$AC/app WORK=$AC/kept/work DRY=0; echo code=\$(app_code)'"
ctl pipeline-app-code-env-pass 0 '^code=ENV1$' -- bash -c "UPG_APP_CODE=ENV1 bash -c '. $AC/fn.sh; APP=$AC/app WORK=$AC/kept/work DRY=0; echo code=\$(app_code)'"
# rung2_cids (cold CMM): rung 1 updated 7 modules, which then carry content id 0, and rung 2's localedits stopped for a
# hand-written localedits.args. rung 2 now gets --cid lines from rung 1's plan.txt; a module the args already name stays.
R2C=$T/rung2cids; mkdir -p $R2C
printf '%s\n' '# plan' '117187 3.22.0 Atlas_Core' '116540 3.11.8 DataWidgets' '# association targets last' '23513 4.5.0 Administration' > $R2C/plan.txt
printf '%s\n' '--cid=DataWidgets=999' > $R2C/args
awk '/^rung2_cids\(\) \{/,/^}$/' $B/cloud/upgrade-pipeline.sh > $R2C/fn.sh
ctl pipeline-rung2-cids-pass 0 '^--cid=Atlas_Core=117187$' '^--cid=Administration=23513$' '^--cid=DataWidgets=999$' '!DataWidgets=116540' '!plan' -- bash -c ". $R2C/fn.sh; rung2_cids $R2C/plan.txt $R2C/args; cat $R2C/args"
ctl pipeline-rung2-cids-wired-pass 0 'rung2_cids "\$WORK/plan.txt" "\$WORK/rung2/localedits.args"' -- grep -n 'rung2_cids "' $B/cloud/upgrade-pipeline.sh
# localedits_args: a line of localedits.args is split into words. The two-word form the triage stop text shows
# (`--cid Administration=23513`) was passed as ONE argv word and localedits.py exited 2 (field run ERRH); the
# `--cid=Mod=ID` form rung2_cids writes stays one word, comments and blank lines are skipped.
LA=$T/ledargs; mkdir -p $LA
printf '%s\n' '# comment' '  # indented note' '--cid Administration=23513' '' '--cid=Atlas_Core=117187' '--proxy   Foo=1.2.3' > $LA/args
awk '/^localedits_args\(\) \{/,/^}$/' $B/cloud/upgrade-pipeline.sh > $LA/fn.sh
ctl pipeline-localedits-args-split-catch 0 '^--cid$' '^Administration=23513$' '^--proxy$' '^Foo=1\.2\.3$' '!--cid Administration' -- bash -c ". $LA/fn.sh && localedits_args $LA/args"
ctl pipeline-localedits-args-oneword-pass 0 '^--cid=Atlas_Core=117187$' '!comment' '!^#$' '!^note$' -- bash -c ". $LA/fn.sh && localedits_args $LA/args"
ctl pipeline-localedits-args-wired-pass 0 'localedits_args "\$WORK/localedits.args"' -- grep -n 'localedits_args "' $B/cloud/upgrade-pipeline.sh

# submit-learnings.sh: a sandbox repo with a local bare remote. The checks refuse a denylisted name, a home folder path,
# internal brain text sent to the toolkit, and a brain inbox inside the toolkit repo; a clean draft is pushed as a
# learnings/ branch cut from the remote, and leaves the inbox. A file remote opens no PR.
SL=$T/submit; mkdir -p $SL; git init -q --bare -b main $SL/origin.git
git clone -q $SL/origin.git $SL/repo 2> /dev/null; mkdir -p $SL/repo/upgrade-toolkit/contrib/inbox
cp $TK/contrib/inbox/README.md $TK/contrib/inbox/TEMPLATE.md $SL/repo/upgrade-toolkit/contrib/inbox/
git -C $SL/repo add -A && git -C $SL/repo -c user.email=ctl@example.invalid -c user.name=ctl commit -qm init && git -C $SL/repo push -q origin main 2> /dev/null
git -C $SL/repo remote set-head origin main
SI=$SL/repo/upgrade-toolkit/contrib/inbox
sl() { GIT_AUTHOR_NAME=ctl GIT_AUTHOR_EMAIL=ctl@example.invalid GIT_COMMITTER_NAME=ctl GIT_COMMITTER_EMAIL=ctl@example.invalid bash $B/submit-learnings.sh "$@"; }
ctl submit-nothing-pass 0 'nothing to submit' -- sl toolkit --inbox $SI
printf '# CE9987 frob\nfrom the Acmecorp run\n' > $SI/2026-01-02-HV1-deny.md
ctl submit-denylist-catch 1 '2026-01-02-HV1-deny\.md:2:.*denylisted name' 'REFUSED' -- sl toolkit --inbox $SI
rm $SI/2026-01-02-HV1-deny.md; printf '# x\nlog at /home/jdoe/run/check.log\nlog at /home/<user>/run/ok.log\n' > $SI/2026-01-02-HV1-home.md
ctl submit-home-path-catch 1 'HV1-home\.md:2:.*home folder path' '!HV1-home\.md:3:' -- sl toolkit --inbox $SI
rm $SI/2026-01-02-HV1-home.md; cp $HV/bi/2026-01-02-HV1-upgrade.md $SI/
ctl submit-internal-to-toolkit-catch 1 'internal text, belongs in the brain' -- sl toolkit --inbox $SI
